class DelayInefficient {
  private int delayRec(int[] times, int i) {
    int n = times.length;
    if (i >= n - 3) {
      return times[i];
    }
    return times[i] + Math.min(Math.min(delayRec(times, i + 1),
        delayRec(times, i + 2)),
        delayRec(times, i + 3));
  }

  public int solve(int[] times) {
    int n = times.length;
    if (n < 3) {
      return 0;
    }
    return Math.min(Math.min(delayRec(times, 0),
        delayRec(times, 1)),
        delayRec(times, 2));
  }
}

