class DelayMemoized {
  private int[] memo;

  private int delayRec(int[] times, int i) {
    int n = times.length;
    if (i >= n - 3) {
      return times[i];
    }
    if (memo[i] != -1) {
      return memo[i];
    }
    memo[i] = times[i] + Math.min(Math.min(delayRec(times, i + 1),
        delayRec(times, i + 2)),
        delayRec(times, i + 3));
    return memo[i];
  }

  public int solve(int[] times) {
    int n = times.length;
    if (n < 3) {
      return 0;
    }
    memo = new int[n];
    Arrays.fill(memo, -1);
    return Math.min(Math.min(delayRec(times, 0),
        delayRec(times, 1)),
        delayRec(times, 2));
  }
}

